"""Intent tests for M1-T20: maximum drawdown with its peak and trough dates (RISK-05, TC-08)."""

import json
from pathlib import Path
from typing import Any

import pytest
from risk import Drawdown, Returns, max_drawdown

TESTS = Path(__file__).resolve().parents[2]
TC08 = TESTS / "fixtures" / "risk" / "TC-08"
SAMPLES = TESTS / "contracts"


def _load(path: Path) -> Any:
    return json.loads(path.read_text())


def _returns(raw: dict[str, Any]) -> Returns:
    return Returns(
        base_date=raw["base_date"],
        dates=tuple(raw["dates"]),
        tickers=tuple(raw["tickers"]),
        values={t: tuple(v) for t, v in raw["values"].items()},
    )


def _by_ticker(result: tuple[Drawdown, ...]) -> dict[str, Drawdown]:
    return {d.ticker: d for d in result}


@pytest.fixture
def tc08() -> tuple[tuple[Drawdown, ...], list[dict[str, Any]], float]:
    inp = _load(TC08 / "input.json")
    exp = _load(TC08 / "expected.json")
    return max_drawdown(_returns(inp["returns"])), exp["drawdowns"], exp["tol"]


@pytest.mark.intent
def test_tc08_one_drawdown_per_ticker_in_order(tc08: Any) -> None:
    result, expected, _ = tc08
    assert isinstance(result, tuple)
    assert all(isinstance(d, Drawdown) for d in result)
    assert [d.ticker for d in result] == [e["ticker"] for e in expected]


@pytest.mark.intent
@pytest.mark.parametrize("ticker", ["X", "Y", "Z"])
def test_tc08_depth(tc08: Any, ticker: str) -> None:
    result, expected, tol = tc08
    exp = next(e for e in expected if e["ticker"] == ticker)
    got = _by_ticker(result)[ticker]
    assert got.depth == pytest.approx(exp["depth"], abs=tol)


@pytest.mark.intent
@pytest.mark.parametrize("ticker", ["X", "Y", "Z"])
def test_tc08_peak_and_trough_dates_exact(tc08: Any, ticker: str) -> None:
    result, expected, _ = tc08
    exp = next(e for e in expected if e["ticker"] == ticker)
    got = _by_ticker(result)[ticker]
    assert (got.peak_date, got.trough_date) == (exp["peak_date"], exp["trough_date"])


@pytest.mark.intent
def test_tc08_invariants_hold(tc08: Any) -> None:
    result, _, _ = tc08
    for d in result:
        assert d.depth <= 0
        assert d.peak_date <= d.trough_date


@pytest.mark.intent
def test_sample_returns_drawdown_invariants() -> None:
    """On the contract sample: the rising ticker has no fall, dated at base_date."""
    raw = _load(SAMPLES / "risk.Returns" / "sample.json")
    returns = _returns(raw)
    result = _by_ticker(max_drawdown(returns))
    assert set(result) == set(returns.tickers)
    for d in result.values():
        assert d.depth <= 0
        assert d.peak_date <= d.trough_date
        assert d.peak_date in (returns.base_date, *returns.dates)
        assert d.trough_date in (returns.base_date, *returns.dates)
    rising = result["BBB"]
    assert rising.depth == 0
    assert rising.peak_date == returns.base_date
    assert rising.trough_date == returns.base_date


@pytest.mark.intent
def test_tie_takes_first_trough() -> None:
    """Two equal falls from the same peak: the first trough's dates are reported."""
    up = 0.1
    returns = Returns(
        base_date="2024-01-01",
        dates=("2024-01-02", "2024-01-03", "2024-01-04", "2024-01-05"),
        tickers=("T",),
        values={"T": (up, -up, up, -up)},
    )
    (d,) = max_drawdown(returns)
    assert d.peak_date == "2024-01-02"
    assert d.trough_date == "2024-01-03"
    assert d.depth < 0

